 for(const owner of [A,B])store.db.prepare('INSERT INTO positions(scan_id,task_key,owner,token_id,holding) VALUES(?,?,?,?,?)').run(holderId,`base:${TOKEN}`,owner,metadata.id,JSON.stringify({...walletHolding,tokenId:metadata.id}));
