  const cz=await service.topics(25,'cs');assert.equal(cz.items.length,3,'translation failure cannot remove topics');assert.equal(cz.items[0].translations.cz.name,'Solana odkládá akci Shanghai kvůli limitu účastníků');assert.equal(cz.items[0].translations.cz.summary,'Organizátoři akci odložili poté, co místo dosáhlo limitu návštěvníků; zůstalo beze změny. SOL');assert.equal(cz.items[0].translationStatus,'success');assert.ok(cz.items[0].translations.cz.summary.includes('SOL'),'ticker is preserved');assert.ok(cz.items[1].translations.cz.summary.includes('5%'),'numbers are preserved');assert.equal(translationCalls,1,'all six title/description strings use one batch provider call');assert.equal(db.prepare('SELECT COUNT(*) AS n FROM aixbt_translation_cache WHERE source=? AND target_language=?').get('AIXBT','cs').n,3,'only successful per-topic Czech translations are stored');
