  assert.match(appSource,/items\.map\(\(item,index\)=>/,'all returned projects are rendered into the carousel without slicing');
  assert.match(appSource,/dashboard-moni-card-stats/,'project cards show score, Smart metrics, change, and metadata');
  assert.match(source,/\.dashboard-source-card\.dashboard-moni-trending \.dashboard-moni-list\{[^}]*grid-auto-flow:column;grid-auto-columns:calc\(\(100% - 20px\)\/3\)[^}]*overflow-x:auto;overflow-y:hidden;scrollbar-width:none/,'MONI carousel clips horizontal overflow behind its navigation');
  assert.match(source,/\/\* External discovery sources use a full-width stack; MONI shows four projects on desktop\. \*\/\s*\.dashboard-source-grid\{grid-template-columns:minmax\(0,1fr\);align-items:start\}/,'external cards stack in a single full-width column');
  assert.match(source,/\.dashboard-source-card\.dashboard-moni-trending \.dashboard-moni-list\{grid-auto-columns:calc\(\(100% - 30px\)\/4\)\}/,'wide desktop shows four MONI cards');
  assert.match(source,/@media\(max-width:1250px\)\{\.dashboard-source-card\.dashboard-moni-trending \.dashboard-moni-list\{grid-auto-columns:calc\(\(100% - 20px\)\/3\)\}\}/,'medium carousel shows three cards');
  assert.match(source,/@media\(max-width:980px\)\{\.dashboard-source-card\.dashboard-moni-trending \.dashboard-moni-list\{grid-auto-columns:calc\(\(100% - 10px\)\/2\)\}\}/,'narrow tablet carousel shows two cards');
  assert.match(source,/@media\(max-width:700px\)\{\.dashboard-source-card\.dashboard-moni-trending \.dashboard-moni-list\{grid-auto-columns:100%\}\}/,'mobile carousel shows one card');
  assert.match(source,/\.dashboard-source-grid\{align-items:start\}/,'external cards are not stretched to match AIXBT height');
  assert.match(source,/\.dashboard-source-card\.dashboard-moni-trending\{height:auto;min-height:220px;max-height:none;align-self:start;padding:10px 14px\}/,'MONI card sizes to carousel content independently of AIXBT');
  assert.match(source,/\.dashboard-moni-carousel-nav button:disabled\{opacity:\.35;cursor:not-allowed\}/,'disabled arrow state is visually distinct');
  assert.match(source,/\.dashboard-moni-row\{box-sizing:border-box;display:flex;flex-direction:column/,'MONI projects use compact cards rather than vertical list rows');
  assert.doesNotMatch(appSource,/accounts\/\$\{[^}]+\}\/info\/full/,'dashboard does not enrich profiles');
  assert.match(htmlSource,/EXTERNÍ SIGNÁLY[\s\S]*?Discovery z externích zdrojů[\s\S]*?dashboard-source-grid[\s\S]*?Discovery · MONI[\s\S]*?Trending · AIXBT[\s\S]*?MOJE DATA/,'External Signals show MONI before AIXBT and precede My Data');
  assert.match(htmlSource,/MOJE DATA[\s\S]*?dashboard-internal-grid[\s\S]*?Co drží moje wallets[\s\S]*?Poslední korelace[\s\S]*?<\/section>[\s\S]*?id="dashboard-research-title">MŮJ RESEARCH/,'My Research is a separate section after the My Data panels');
  assert.doesNotMatch(htmlSource,/Pokračovat ve výzkumu/,'the removed Continue research block is absent from Dashboard');
  assert.match(htmlSource,/dashboard-aixbt-panel dashboard-source-card/,'AIXBT is an extensible external source card');
  assert.match(htmlSource,/dashboard-moni-trending dashboard-source-card/,'MONI is an extensible external source card');
  assert.match(source,/\.dashboard-source-grid\{display:grid;grid-template-columns:repeat\(2,minmax\(0,1fr\)\);gap:16px;align-items:stretch/,'base source-card grid remains defined before the full-width override');
  assert.match(source,/\.dashboard-source-card\{[^}]*height:900px;max-height:none;min-height:600px/,'AIXBT retains enough height for a long topic list');
  assert.match(source,/@media\(max-width:980px\)\{\.dashboard-source-grid\{grid-template-columns:minmax\(0,1fr\)\}\.dashboard-source-card\{height:680px;max-height:none;min-height:480px\}\}/,'external cards stack responsively and remain equally sized');
  assert.match(source,/\.dashboard-source-card \.dashboard-aixbt-list,\.dashboard-source-card \.dashboard-moni-list\{[^}]*overflow-y:auto;overflow-x:hidden/,'both external card bodies scroll vertically and clip horizontal overflow');
  assert.match(source,/\.dashboard-source-card\.dashboard-moni-trending,\.dashboard-source-card\.dashboard-aixbt-panel\{grid-column:1\/-1\}/,'MONI and AIXBT cards span the full external section width');
